local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local ResourceModule = CS.Engine.Modules.ResourceModule
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool
local LuaChapterEffect = CS.LuaChapterEffect
local Material = CS.UnityEngine.Material
local GameObject = CS.UnityEngine.GameObject

---@class ScreenComicEffect : BaseEffect
local ScreenComicEffect = Class("ScreenComicEffect", BaseEffect)

local NewChapterConstants = import('Game.Chapter.NewChapterConstants')

function ScreenComicEffect:__init()
    self.isFinish = nil
end

function ScreenComicEffect:__delete()
    self.isFinish = nil
end

function ScreenComicEffect:Initialize(parameters)
    --base.StartEffect(self, parameters)
    self.isFinish = false
    xlua.private_accessible(LuaChapterEffect)
end

function ScreenComicEffect:StartEffect(object)
    --base.StartEffect(self, object)
    self.co = cs_coroutine.start(function()
        local loader = ResourceModule.LoadBundleAsync(NewChapterConstants.ComicMaterialPath, nil, true)
        while not loader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end

        if loader.IsSuccess then
            local mat = GameObject.Instantiate(loader.ResultObject)
            --xlua.cast(mat, typeof(Material))
            local script = object.gameObject:EnsureComponent(typeof(LuaChapterEffect))

            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            mat:SetFloat("_Is_Dot", 0)
            script._effMat = mat
            script.enabled = true
            
            self.effectMat = mat
            self.loader = loader
        else
            loader:Release()
        end

        
        self.isFinish = true
        self.co = nil
    end)
end

function ScreenComicEffect:IsFinish()
    return self.isFinish
end

function ScreenComicEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function ScreenComicEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    KTool.SafeDelete(self.effectMat)
    if self.co ~= nil then
        cs_coroutine.stop(self.co)
    end
    if not isNull(self.loader) then
        self.loader:Release()
    end
end

return ScreenComicEffect